analyze.mjs.text:
// Classifies a set of per-table probe results (real HTTP responses,
// collected by probe.mjs's live requests, or pasted in by hand) into a
// verdict about whether the anon key can read real rows from a table with no
// Row Level Security in effect.
//
// Pure function, no I/O, no network -- imported identically by the CLI
// (check.mjs, which fetches for real) and the browser page (index.html,
// which can fetch for real too, since neither header PostgREST reads is
// forbidden the way CORS's Origin is -- see probe.mjs's header comment).
//
// What each classification means, in PostgREST/Supabase's own terms:
//
//   exposed   The anon key received at least one real row (or a nonzero
//             exact count) from this table. This is the CVE-2025-48757 /
//             "170+ Lovable apps" shape: RLS is off (or a policy exists but
//             is broader than intended), and the anon role's default schema
//             USAGE grant is enough on its own to read it.
//   blocked   HTTP 401/403 -- either RLS is enabled and its policies reject
//             this key outright, or the anon role has no grant on the table
//             at all. Either way, nothing was readable. This is the healthy
//             outcome.
//   unconfirmed  HTTP 200 with zero rows and an exact count of zero (or no
//             count header at all). This is genuinely ambiguous: it is the
//             same response whether RLS is correctly blocking every row *or*
//             the table simply has no rows yet. Reported as its own category
//             rather than folded into either "exposed" or "blocked", because
//             claiming either one from this response alone would be a
//             guess -- the report says exactly that and suggests the one
//             way to resolve it (insert one throwaway test row, or check
//             from the Supabase dashboard directly).
//   error     The request itself did not complete cleanly (network error,
//             timeout, malformed response) or returned a status this tool
//             does not classify (e.g. 5xx). Never read as either finding --
//             an error is not evidence of anything about RLS.

function classifyOne(result) {
  const table = result?.table ?? '(unknown table)';
  if (!result || result.ok === false && result.status == null) {
    return { table, category: 'error', status: null, rowsReturned: 0, totalCount: null, columns: [], error: result?.error ?? 'request failed' };
  }
  const status = result.status ?? null;
  const rowsReturned = result.rowsReturned ?? 0;
  const totalCount = result.totalCount ?? null;
  const columns = result.columns ?? [];

  if (status === 401 || status === 403) {
    return { table, category: 'blocked', status, rowsReturned, totalCount, columns, error: null };
  }
  if (status != null && status >= 200 && status < 300) {
    if (rowsReturned > 0 || (totalCount != null && totalCount > 0)) {
      return { table, category: 'exposed', status, rowsReturned, totalCount, columns, error: null };
    }
    return { table, category: 'unconfirmed', status, rowsReturned, totalCount, columns, error: null };
  }
  return { table, category: 'error', status, rowsReturned, totalCount, columns, error: result.error ?? `unexpected HTTP ${status}` };
}

/**
 * @param {string} baseUrl - the project's REST base URL, for display only
 * @param {object[]} results - probe.mjs's per-table results (or the CLI's
 *   pasted JSON), each `{table, ok, status, rowsReturned, totalCount, columns, error}`
 * @param {{schemaError?: string|null, truncated?: boolean}} [meta]
 */
export function buildReport(baseUrl, results, meta = {}) {
  const list = Array.isArray(results) ? results : [];
  const classified = list.map(classifyOne);

  const findings = classified
    .filter((c) => c.category === 'exposed')
    .map((c) => ({
      id: 'table-readable-without-rls',
      severity: 'danger',
      table: c.table,
      title: `"${c.table}" is readable by anyone holding this anon key`,
      detail:
        (c.totalCount != null
          ? `${c.totalCount} row(s) total, `
          : '') +
        `${c.rowsReturned} row(s) returned to an unauthenticated request with no session, no login, ` +
        `and no server of ours involved -- the same request any visitor's browser (or curl) can send. ` +
        (c.columns.length > 0 ? `Columns visible: ${c.columns.join(', ')}.` : ''),
      evidenceStatus: `HTTP ${c.status}`,
    }));

  const unconfirmed = classified.filter((c) => c.category === 'unconfirmed');
  const blocked = classified.filter((c) => c.category === 'blocked');
  const errors = classified.filter((c) => c.category === 'error');

  const schemaError = meta.schemaError ?? null;
  const incomplete = Boolean(schemaError) || errors.length > 0;

  return {
    baseUrl,
    tablesChecked: classified.length,
    truncated: Boolean(meta.truncated),
    schemaError,
    classified,
    findings,
    unconfirmed,
    blocked,
    errors,
    dangerCount: findings.length,
    ok: !schemaError && findings.length === 0,
    incomplete,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: reads a Supabase project's own public schema listing, then sends one
// real, read-only GET per table using the anon key you provide, and reports
// which tables return real rows to that unauthenticated request -- the
// CVE-2025-48757 / "missing RLS" exposure class. Your machine, your
// project's REST endpoint -- no request goes through this portfolio.
//
//   node check.mjs <project-url> <anon-key> [--json] [--timeout <ms>]
//
// Only run this against a Supabase project you own or are authorised to
// test. The anon key is meant to be public-ish by Supabase's own design (it
// is embedded in every client app that uses the project), but the table
// contents it can reveal are not -- treat this the same as you would `curl`
// aimed at someone else's server. This never writes, updates, or deletes
// anything: every request is GET, capped at one row, with an exact count.
//
// Exit code 0 when the schema was readable and no table returned a real row
// to the anon key; 1 when at least one table is exposed or the schema/some
// tables could not be checked at all.

import { runProbes } from './probe.mjs';
import { buildReport } from './analyze.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Project: ${report.baseUrl}`);
  lines.push(`Tables checked: ${report.tablesChecked}${report.truncated ? ' (list truncated at the cap)' : ''}`);
  lines.push('');

  if (report.schemaError) {
    lines.push(`Could not read the project's schema: ${report.schemaError}`);
    lines.push('Check the project URL and anon key, then re-run.');
    return lines.join('\n');
  }

  if (report.findings.length === 0) {
    lines.push('No table returned a real row to this anon key.');
  } else {
    for (const f of report.findings) {
      lines.push(`!! [DANGER] ${f.title}`);
      lines.push(`     ${f.detail}`);
      lines.push(`     evidence: ${f.evidenceStatus}`);
      lines.push('');
    }
  }

  if (report.unconfirmed.length > 0) {
    lines.push('');
    lines.push(
      `${report.unconfirmed.length} table(s) returned zero rows with no way to tell "RLS is blocking this" ` +
        `from "this table is just empty": ${report.unconfirmed.map((c) => c.table).join(', ')}. ` +
        'Insert one throwaway test row (or check the Supabase dashboard directly) to resolve which.',
    );
  }
  if (report.errors.length > 0) {
    lines.push('');
    lines.push(`${report.errors.length} table(s) could not be checked: ${report.errors.map((c) => `${c.table} (${c.error})`).join('; ')}`);
  }
  if (report.blocked.length > 0) {
    lines.push('');
    lines.push(`${report.blocked.length} table(s) correctly rejected this anon key (401/403): ${report.blocked.map((c) => c.table).join(', ')}`);
  }

  lines.push('');
  lines.push(
    'This is evidence from the requests above, not a full security audit -- see README.md for ' +
      'what this tool does and does not check.',
  );
  return lines.join('\n');
}

function parseArgs(argv) {
  const positional = argv.filter((a) => !a.startsWith('--'));
  const args = { projectUrl: positional[0] ?? null, anonKey: positional[1] ?? null, json: false, timeoutMs: undefined };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') args.json = true;
    else if (argv[i] === '--timeout') args.timeoutMs = Number(argv[++i]);
  }
  return args;
}

/** Pure orchestration: given a probe function (real network, or a stub in
 * tests), fetch and classify. Kept separate from main() so tests can inject
 * a fake `probeFn` instead of hitting the network. */
export async function runCheck(projectUrl, anonKey, { probeFn = runProbes, timeoutMs } = {}) {
  const { baseUrl, results, schemaError, truncated } = await probeFn(projectUrl, anonKey, timeoutMs ? { timeoutMs } : {});
  return buildReport(baseUrl, results, { schemaError, truncated });
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.projectUrl || !args.anonKey) {
    console.error('Usage: node check.mjs <project-url> <anon-key> [--json] [--timeout <ms>]');
    console.error('Only run this against a Supabase project you own or are authorised to test.');
    process.exit(2);
  }
  try {
    // eslint-disable-next-line no-new
    new URL(args.projectUrl);
  } catch {
    console.error(`Not a valid URL: ${args.projectUrl}`);
    process.exit(2);
  }

  const report = await runCheck(args.projectUrl, args.anonKey, { timeoutMs: args.timeoutMs });

  if (args.json) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

probe.mjs.text:
// Sends the real HTTP requests this check depends on, using the global
// `fetch` -- deliberately, so this exact module runs unmodified from the CLI
// (Node 22's built-in fetch) and from the browser page (index.html imports it
// directly). That is possible here in a way it is not for
// ventures/cors-misconfig-check's probe.mjs: the headers PostgREST (Supabase's
// REST layer) actually reads -- `apikey` and `Authorization: Bearer <key>` --
// are ordinary request headers, not one of the Fetch spec's forbidden names
// the way `Origin` is. And PostgREST answers with
// `Access-Control-Allow-Origin: *` by design (it is meant to be called
// directly from a browser tab, from whatever site embeds the project), so a
// visitor's own browser can run the real check with no server of ours in the
// middle.
//
// This module only ever talks to the one project URL a caller names, using
// the anon key that same caller supplies. It makes no other network call,
// reads no local files, and sends the key nowhere but that one project's own
// REST endpoint -- the same request the project's own client-side app
// already makes on every page load.

const DEFAULT_TIMEOUT_MS = 10_000;
const USER_AGENT =
  'supabase-rls-check/1 (+https://duncan-haywood.github.io/monorepo-projects/supabase-rls-check/)';

function normalizeBaseUrl(projectUrl) {
  const trimmed = String(projectUrl || '').trim().replace(/\/+$/, '');
  const parsed = new URL(trimmed);
  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') {
    throw new Error(`unsupported scheme: ${parsed.protocol}`);
  }
  return parsed.origin;
}

async function timedFetch(url, init, timeoutMs, fetchImpl) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  if (typeof doFetch !== 'function') {
    throw new Error('no fetch implementation available in this environment');
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await doFetch(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Reads PostgREST's own root OpenAPI document (`GET /rest/v1/`) and returns
 * the table/view names it lists under `paths` (excluding the root path
 * itself). This is the same schema listing the anon key can already see
 * before any table-level request -- PostgREST publishes it so client
 * libraries can introspect the API, and it requires no more privilege than
 * the anon role's default `USAGE` grant on the exposed schema, which is what
 * every fresh Supabase project starts with regardless of whether RLS is on.
 */
export async function listTables(baseUrl, anonKey, { timeoutMs = DEFAULT_TIMEOUT_MS, fetchImpl } = {}) {
  const url = `${baseUrl}/rest/v1/`;
  let res;
  try {
    res = await timedFetch(
      url,
      { method: 'GET', headers: { apikey: anonKey, Authorization: `Bearer ${anonKey}`, 'user-agent': USER_AGENT, accept: 'application/openapi+json, application/json' } },
      timeoutMs,
      fetchImpl,
    );
  } catch (err) {
    return { ok: false, tables: [], error: err.message ?? String(err) };
  }
  if (!res.ok) {
    return { ok: false, tables: [], status: res.status, error: `HTTP ${res.status} reading the schema root -- check the project URL and anon key` };
  }
  let body;
  try {
    body = await res.json();
  } catch (err) {
    return { ok: false, tables: [], status: res.status, error: `could not parse the schema document as JSON: ${err.message}` };
  }
  const paths = body && typeof body === 'object' ? body.paths : null;
  if (!paths || typeof paths !== 'object') {
    return { ok: false, tables: [], status: res.status, error: 'schema document has no "paths" -- this may not be a PostgREST/Supabase REST endpoint' };
  }
  const tables = Object.keys(paths)
    .filter((p) => p.startsWith('/') && p !== '/' && !p.includes('rpc/'))
    .map((p) => p.slice(1));
  return { ok: true, tables, status: res.status, error: null };
}

/**
 * Requests exactly one row from `table` with an exact row count (via
 * `Prefer: count=exact` and a `Range: 0-0`), which is enough to know whether
 * the anon key can read real rows without ever pulling a whole table into
 * memory. Never mutates anything -- this sends GET only.
 */
export async function probeTable(baseUrl, anonKey, table, { timeoutMs = DEFAULT_TIMEOUT_MS, fetchImpl } = {}) {
  const url = `${baseUrl}/rest/v1/${encodeURIComponent(table)}?select=*&limit=1`;
  let res;
  try {
    res = await timedFetch(
      url,
      {
        method: 'GET',
        headers: {
          apikey: anonKey,
          Authorization: `Bearer ${anonKey}`,
          'user-agent': USER_AGENT,
          Range: '0-0',
          Prefer: 'count=exact',
        },
      },
      timeoutMs,
      fetchImpl,
    );
  } catch (err) {
    return { table, ok: false, status: null, rowsReturned: 0, totalCount: null, columns: [], error: err.message ?? String(err) };
  }

  let rows = [];
  let parseError = null;
  try {
    rows = await res.json();
    if (!Array.isArray(rows)) rows = [];
  } catch (err) {
    parseError = err.message ?? String(err);
  }

  const contentRange = res.headers.get('content-range'); // e.g. "0-0/42" or "*/0"
  let totalCount = null;
  if (contentRange) {
    const m = /\/(\d+|\*)$/.exec(contentRange);
    if (m && m[1] !== '*') totalCount = Number(m[1]);
  }

  return {
    table,
    ok: res.ok,
    status: res.status,
    rowsReturned: rows.length,
    totalCount,
    columns: rows.length > 0 && rows[0] && typeof rows[0] === 'object' ? Object.keys(rows[0]) : [],
    error: !res.ok ? `HTTP ${res.status}` : parseError,
  };
}

/**
 * Full run: normalise the URL, list the tables the anon key can see in the
 * schema, then probe each one for a real, readable row. `tables`, if given,
 * skips the schema-listing request and checks exactly those names instead --
 * useful when a project has disabled the OpenAPI root (some do) but the
 * caller already knows which tables to check.
 */
export async function runProbes(projectUrl, anonKey, { tables: givenTables, timeoutMs, fetchImpl, maxTables = 200 } = {}) {
  const baseUrl = normalizeBaseUrl(projectUrl);

  let tables = givenTables;
  let schemaError = null;
  if (!tables) {
    const listed = await listTables(baseUrl, anonKey, { timeoutMs, fetchImpl });
    if (!listed.ok) {
      return { baseUrl, tables: [], schemaError: listed.error, results: [] };
    }
    tables = listed.tables;
  }

  const capped = tables.slice(0, maxTables);
  const results = await Promise.all(
    capped.map((table) => probeTable(baseUrl, anonKey, table, { timeoutMs, fetchImpl })),
  );
  return { baseUrl, tables: capped, schemaError, results, truncated: tables.length > capped.length };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// project URL, the anon key, or anything about which tables were checked or
// what came back -- that is exactly the kind of thing that must not be
// transmitted or retained anywhere, and this tool never reads it off the
// visitor's machine either.

const STORAGE_KEY = 'supabase-rls-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters: opting out
// *removes* the counters, so a flag stored inside them would be deleted by
// the very act it records.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
